"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type TextMorphPrimitiveProps = ComponentProps<typeof motion.div>;

export function TextMorphPrimitive({ children, ...props }: TextMorphPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {opacity: 0,y: 5}}
      animate={{opacity: 1,y: 0}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 0.24, ease: [0.23, 1, 0.32, 1], delay: 0.12 }}

    >
      {children}
    </motion.div>
  );
}
